    max = steps,
    contentDescription = stringResource(Res.string.setup),
    style = ProgressCircleStyle(size = 72.dp, strokeWidth = 8.dp),
    tagKey = "setup"
) {
    PantrixText(text = "$done/$steps", modifier = Modifier.clearAndSetSemantics { })
}

Row(verticalAlignment = Alignment.CenterVertically) {
    PantrixText(text = total, style = PantrixTheme.typography.title)
    PantrixSparkline(values = lastThirtyDays, contentDescription = null)
}

PantrixTreemap(
    items = departments.map { department ->
        TreemapItem(
            key = department.id,
            name = department.name,
            children = department.teams.map { TreemapItem(it.id, it.name, it.budget) }
        )
    },
    tagKey = "budget"
)

val inbox = rememberListDetailState()
PantrixListDetailScaffold(
    state = inbox,
    list = { Messages(onOpen = { id -> inbox.select(id) }) },
    detail = { id ->
        Message(id, onBack = if (isSinglePane) ({ inbox.back() }) else null)
    },
    modifier = Modifier.fillMaxSize(),
    emptyDetail = { PantrixText("Choose a message") }
)

